{"command": "sleep 45; echo "=== events in last 30s ==="; NOW=$(date -u +%s); kubectl -n default get events -o json | python3 -c "
import json,sys,datetime
now=$NOW
d=json.load(sys.stdin)
for e in d['items']:
    ts=e.get('lastTimestamp') or e['metadata']['creationTimestamp']
    t=datetime.datetime.strptime(ts,'%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=datetime.timezone.utc).timestamp()
    if now-t<=30: print(int(now-t),'s ago',e['type'],e['reason'],e['involvedObject']['name'],e.get('message','')[:90])
"; echo "=== pod readiness ==="; kubectl -n default get pods -o custom-columns=NAME:.metadata.name,READY:.status.containerStatuses[*].ready,RESTARTS:.status.containerStatuses[*].restartCount; kubectl -n default get deploy app"}

